INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > IT-Arbeitsplätze im Kontext > Leistungsportfolio Ausbildungsbetrieb > Arbeitsumgebungen & IT-Systeme
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind Arbeitsumgebungen im Ausbildungsbetrieb immer physische Büros?', 2, '[{"text": "Nein", "correct": true, "because": "Auch virtuelle oder hybride Umgebungen möglich"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen IT-Systeme im Ausbildungsbetrieb den Anforderungen der Auszubildenden entsprechen?', 2, '[{"text": "Ja", "correct": true, "because": "Sichern effektive Ausbildung"}, {"text": "Nein", "correct": false, "because": "Anpassung ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Arbeitsumgebungen ohne IT-Systeme im Ausbildungsbetrieb existieren?', 2, '[{"text": "Nein", "correct": true, "because": "IT-Systeme sind für moderne Ausbildung nötig"}, {"text": "Ja", "correct": false, "because": "IT ist integral"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Flexibilität von IT-Systemen ein Vorteil für Arbeitsumgebungen im Ausbildungsbetrieb?', 2, '[{"text": "Ja", "correct": true, "because": "Ermöglicht Anpassung an Bedürfnisse"}, {"text": "Nein", "correct": false, "because": "Flexibilität ist nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Arbeitsumgebungen und IT-Systeme im Ausbildungsbetrieb unabhängig voneinander?', 2, '[{"text": "Nein", "correct": true, "because": "Sie beeinflussen sich gegenseitig"}, {"text": "Ja", "correct": false, "because": "Verknüpfung besteht"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Arbeitsumgebung ist typisch für einen Ausbildungsbetrieb?', 3, '[{"text": "Hybride Umgebung", "correct": true, "because": "Kombiniert Büro und Remote"}, {"text": "Nur virtuell", "correct": false, "because": "Weniger üblich"}, {"text": "Outdoor", "correct": false, "because": "Nicht IT-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches IT-System wird oft in Ausbildungsbetrieben eingesetzt?', 2, '[{"text": "Client-Server-System", "correct": true, "because": "Ermöglicht zentralen Zugriff"}, {"text": "Manuelle Rechenmaschine", "correct": false, "because": "Veraltet"}, {"text": "Farbdrucker", "correct": false, "because": "Peripheriegerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Gestaltung von Arbeitsumgebungen entscheidend?', 2, '[{"text": "Ergonomie", "correct": true, "because": "Sichert Gesundheit und Effizienz"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen IT-Systeme im Ausbildungsbetrieb?', 3, '[{"text": "Unterstützung der Ausbildung", "correct": true, "because": "Fördert Lernen und Praxis"}, {"text": "Minimale Kosten", "correct": false, "because": "Sekundär"}, {"text": "Schnelle Installation", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil moderner IT-Systeme im Ausbildungsbetrieb?', 2, '[{"text": "Flexibilität", "correct": true, "because": "Anpassung an Bedürfnisse"}, {"text": "Geringer Preis", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Arbeitsumgebungen gibt es im Ausbildungsbetrieb?', 4, '[{"text": "Büro", "correct": true, "because": "Klassische Umgebung"}, {"text": "Remote", "correct": true, "because": "Heimarbeit"}, {"text": "Hybrid", "correct": true, "because": "Kombination"}, {"text": "Outdoor", "correct": false, "because": "Nicht IT-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche IT-Systeme unterstützen die Ausbildung?', 3, '[{"text": "Lernplattformen", "correct": true, "because": "Fördern Wissen"}, {"text": "Netzwerksysteme", "correct": true, "because": "Vernetzung"}, {"text": "Office-Software", "correct": true, "because": "Praxisnah"}, {"text": "Farbdrucker", "correct": false, "because": "Peripheriegerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten moderne Arbeitsumgebungen im Ausbildungsbetrieb?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Anpassung an Bedürfnisse"}, {"text": "Effizienz", "correct": true, "because": "Optimiert Arbeit"}, {"text": "Zugänglichkeit", "correct": true, "because": "Ortsunabhängig"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei IT-Systemen im Ausbildungsbetrieb auftreten?', 4, '[{"text": "Technische Ausfälle", "correct": true, "because": "Stören Ablauf"}, {"text": "Komplexität", "correct": true, "because": "Erschwert Nutzung"}, {"text": "Kosten", "correct": true, "because": "Hohe Investitionen"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Wahl der Arbeitsumgebung?', 3, '[{"text": "Ausbildungsziele", "correct": true, "because": "Bestimmen Anforderungen"}, {"text": "Technische Ausstattung", "correct": true, "because": "Ermöglicht Umsetzung"}, {"text": "Ergonomie", "correct": true, "because": "Sichert Komfort"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Arbeitsumgebungen im Ausbildungsbetrieb können hybrid sein. b) IT-Systeme sind für die Ausbildung unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hybrid ja, IT-Systeme wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ergonomie ist bei Arbeitsumgebungen entscheidend. b) Arbeitsumgebungen sind immer physisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergonomie ja, auch virtuell möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Lernplattformen unterstützen die Ausbildung. b) IT-Systeme müssen nicht den Anforderungen entsprechen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Plattformen ja, Anpassung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Flexible IT-Systeme fördern die Ausbildung. b) Arbeitsumgebungen können ohne IT-Systeme effizient sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ja, IT nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Technische Ausfälle können die Ausbildung stören. b) Arbeitsumgebungen und IT-Systeme sind unabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausfälle ja, Verknüpfung besteht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

